llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "KNI-272, a peptidomimetic HIV protease inhibitor sharing the C-terminal tert-butyl amide and hydroxyethylamine transition-state motif with the query, showed absolute oral bioavailability of 54.97 ± 19.78% in fasting patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Indinavir, another peptidomimetic protease inhibitor with a tert-butyl amide and hydroxyethylamine core, had systemic bioavailability of 0.60 (0.54–0.66) in humans, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Boceprevir, a peptidomimetic protease inhibitor with a tert-butyl amide and cyclic P2/P1' elements, had approximately 20% oral bioavailability in humans, providing threshold-level supportive evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Remikiren, a large peptidomimetic with tert-butyl and multiple hydrogen-bond donors, had only 0.2% absolute oral bioavailability in healthy volunteers; this is contradictory caution, but its lower structural similarity and different target class reduce transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most relevant analogues are HIV protease inhibitor peptidomimetics KNI-272 and indinavir, both with human absolute oral bioavailability well above 20%; boceprevir is borderline at ~20%. The very low bioavailability of remikiren is a caution, but its lower similarity and different chemotype limit its weight. Overall, the transferable experimental evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the query molecule itself.",
    "All analogue Morgan similarities are low (<0.3), limiting quantitative transferability.",
    "Species, dose, and formulation differences exist among the evidence records, e.g., KNI-272 showed only 12% bioavailability in children.",
    "No direct data on solubility, permeability, or first-pass metabolism for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

